import subprocess, os, shutil, sys
REF="/workspace/executable"
MINE=["python3","/workspace/elfcat.py"]
def run_one(cmd, data, args, cwd):
    shutil.rmtree(cwd,ignore_errors=True); os.makedirs(cwd)
    if data is not None:
        # data can be bytes to write as first arg file if args refers
        name=args[0] if args else "testbin"
        # only write if name doesn't contain path traversal? args in our tests simple
        path=os.path.join(cwd,name)
        os.makedirs(os.path.dirname(path),exist_ok=True)
        with open(path,"wb") as f: f.write(data)
    p=subprocess.Popen(cmd+args,cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    pid=p.pid
    out,err=p.communicate()
    # normalize pid in panic
    err=err.replace(f"({pid})".encode(),b"(PID)")
    files={}
    for root,dirs,fs in os.walk(cwd):
        for fn in fs:
            rel=os.path.relpath(os.path.join(root,fn),cwd)
            # exclude input file itself if data and rel==args[0]
            if data is not None and args and rel==args[0]:
                continue
            files[rel]=open(os.path.join(root,fn),"rb").read()
    return p.returncode,out,err,files

def compare(label,data=None,args=["testbin"]):
    r=run_one([REF],data,args,"/tmp/cmp_ref")
    m=run_one(MINE,data,args,"/tmp/cmp_mine")
    ok=r==m
    print(("OK  " if ok else "FAIL"),label, "ref rc",r[0],"mine rc",m[0])
    if not ok:
        if r[0]!=m[0]: print(" rc diff",r[0],m[0])
        if r[1]!=m[1]: print(" stdout ref",r[1][:500],"mine",m[1][:500])
        if r[2]!=m[2]: print(" stderr ref",r[2][:1000],"mine",m[2][:1000])
        if r[3]!=m[3]:
            print(" files ref",list(r[3]),"mine",list(m[3]))
            for k in r[3]:
                if k in m[3] and r[3][k]!=m[3][k]:
                    a=r[3][k]; b=m[3][k]
                    print("  file diff",k,len(a),len(b))
                    # first diff
                    for i,(x,y) in enumerate(zip(a,b)):
                        if x!=y:
                            print("   first diff at",i,repr(a[max(0,i-200):i+200]),"VS",repr(b[max(0,i-200):i+200])); break
                    else:
                        if len(a)!=len(b): print("   prefix same, ref tail",repr(a[len(b):][:200]),"mine tail",repr(b[len(a):][:200]))
    return ok
PY
