p='elfcat.py'; s=open(p).read()
s=s.replace('LOC_ENV_ARGS = "library/std/src/env.rs:871:51"','LOC_ENV_ARGS = "library/std/src/env.rs:871:51"\nLOC_STDIO = "library/std/src/io/stdio.rs:1165:9"')
old='''def write_stdout(text):
    os.write(1, text.encode("utf-8"))


def write_stderr(text):
    os.write(2, text.encode("utf-8"))
'''
new='''def _write_all(fd, data, stream_name):
    try:
        while data:
            written = os.write(fd, data)
            if written <= 0:
                raise OSError(0, "failed to write whole buffer")
            data = data[written:]
    except OSError as e:
        panic(LOC_STDIO, f"failed printing to {stream_name}: {io_error_text(e)}")


def write_stdout(text):
    _write_all(1, text.encode("utf-8"), "stdout")


def write_stderr(text):
    _write_all(2, text.encode("utf-8"), "stderr")


def sanitize_standard_fds():
    for fd, flags in ((0, os.O_RDONLY), (1, os.O_WRONLY), (2, os.O_WRONLY)):
        try:
            os.fstat(fd)
            continue
        except OSError:
            pass
        try:
            newfd = os.open("/dev/null", flags)
        except OSError:
            continue
        if newfd != fd:
            try:
                os.dup2(newfd, fd)
            finally:
                os.close(newfd)
'''
assert old in s; s=s.replace(old,new)
# call sanitizer before main in __main__
old2='''    try:
        code = main(sys.argv)'''
new2='''    sanitize_standard_fds()
    try:
        code = main(sys.argv)'''
assert old2 in s; s=s.replace(old2,new2)
open(p,'w').write(s)
