import os,subprocess
def run(cmd,args,closefd=None,stdout_pipe=False):
    stderr_dest=subprocess.PIPE
    outpipe=None
    # use files for captures when closing fds
    with open('/tmp/capout','wb') as out, open('/tmp/caperr','wb') as err:
        pre = (lambda: os.close(closefd)) if closefd is not None else None
        p=subprocess.run(cmd+args,stdout=out,stderr=err,preexec_fn=pre)
    return p.returncode,open('/tmp/capout','rb').read(),open('/tmp/caperr','rb').read().replace(str(p.pid).encode() if hasattr(p,'pid') else b'',b'')
# subprocess.run doesn't expose pid after, ignore exact panic pid comparison in this ad hoc
for closefd in [1,2,0]:
 for cmd in [['/workspace/executable'],['python3','/workspace/elfcat.py']]:
  print('close',closefd,cmd, run(cmd,['--help'],closefd))
  print('close',closefd,cmd, run(cmd,['missing'],closefd))
# broken pipes
for which in ['stdout','stderr']:
 for cmd in [['/workspace/executable'],['python3','/workspace/elfcat.py']]:
  r,w=os.pipe();os.close(r)
  with open('/tmp/capother','wb') as other:
   kw={'stdout':w if which=='stdout' else other,'stderr':w if which=='stderr' else other}
   p=subprocess.Popen(cmd+(['--help'] if which=='stdout' else ['missing']),**kw); os.close(w); rc=p.wait()
  print('broken',which,cmd,rc,open('/tmp/capother','rb').read())
