import struct
def note(name,desc,typ):
 def pad(f):return f+b'\0'*(((4-len(f)%4)%4))
 return struct.pack('<III',len(name),len(desc),typ)+pad(name)+pad(desc)
notes=note(b'CORE\x00',bytes(range(100)),3)+note(b'CORE\x00',b'NT_PRSTATUS data '*10,1)+note(b'LINUX\x00',b'x'*33,0x200)
